able';
  root.add(turntable);

  const tiltGroup = new THREE.Group();
  tiltGroup.name = 'depth-rotate-tilt';
  turntable.add(tiltGroup);

  let watchScene = null;
  if (config.meshUrl) {
    let gltf = null;
    try {
      gltf = ctx.glbLoader(config.meshUrl);
    } catch (err) {
      gltf = null;
    }
    const source =
      gltf && (gltf.scene || (gltf.scenes && gltf.scenes[0]) || (gltf.isObject3D ? gltf : null));
    if (source) {
      watchScene = source.clone(true);
    }
  }

  if (!watchScene) {
    // Fallback machined-metal placeholder case if the GLB is unavailable.
    const fallbackGeo = new THREE.CylinderGeometry(0.55, 0.6, 2.2, 48, 1, false);
    const fallbackMat = new THREE.MeshPhysicalNodeMaterial({
      color: new THREE.Color('#8a8d94'),
      roughness: 0.52,
      metalness: 0.55,
      clearcoat: 0.2,
      clearcoatRoughness: 0.4,
    });
    watchScene = new THREE.Mesh(fallbackGeo, fallbackMat);
    disposables.push(fallbackGeo, fallbackMat);
  } else {
    watchScene.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(watchScene);
    const size = new THREE.Vector3();
    box.getSize(size);
    const targetHeight = 2.2;
    const scaleFactor = size.y > 0 ? targetHeight / size.y : 1;
    watchScene.scale.setScalar(scaleFactor);
    watchScene.updateMatrixWorld(true);
    const box2 = new THREE.Box3().setFromObject(watchScene);
    const center2 = new THREE.Vector3();
    box2.getCenter(center2);
    watchScene.position.sub(center2);
  }

  tiltGroup.add(watchScene);

  // ---------- accent signal light fixture (small emissive indicator, capped intensity) ----------
  const signalGeo = new THREE.SphereGeometry(0.045, 20, 16);
  const signalMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color('#16161d'),
    roughness: 0.4,
    metalness: 0.2,
  });
  const pulse01 = time.mul(1.6).sin().mul(0.5).add(0.5);
  signalMat.emissiveNode = color('#ff2a38').mul(pulse01.mul(0.9).add(0.7));
  const signalLightFixture = new THREE.Mesh(signalGeo, signalMat);
  signalLightFixture.position.set(1.28, plinthTopY + 0.03, 0.55);
  root.add(signalLightFixture);
  disposables.push(signalGeo, signalMat);

  // ---------- key + rim + accent lighting (node-local; do not assume hub provides lighting) ----------
  const keyLight = new THREE.DirectionalLight(new THREE.Color('#f3f4f8'), 2.4);
  keyLight.position.set(2.4, 3.0, 3.2);
  keyLight.target.position.set(0, 0, 0);
  root.add(keyLight, keyLight.target);

  const rimLight = new THREE.DirectionalLight(new THREE.Color('#e8ecf2'), 1.6);
  rimLight.position.set(-1.8, 1.4, -3.0);
  rimLight.target.position.set(0, 0, 0);
  root.add(rimLight, rimLight.target);

  const accentLight = new THREE.SpotLight(
    new THREE.Color('#ff2a38'),
    3.2,
    6,
    THREE.MathUtils.degToRad(28),
    0.5,
    1.4
  );
  accentLight.position.set(-2.1, 0.4, 1.0);
  accentLight.target.position.set(-0.6, 0.1, 0.3);
  root.add(accentLight, accentLight.target);

  // ---------- text content (MSDF, scene-unit type scale) ----------
  const textEntries =
    Array.isArray(config.textContent) && config.textContent.length
      ? config.textContent
      : DEFAULT_TEXT_CONTENT;

  const headlineY = -1.5;
  const bodyY = headlineY - 0.25;
  const captionY = headlineY - 0.5;
  const roleY = { headline: headlineY, body: bodyY, caption: captionY };

  textEntries.forEach((entry) => {
    const role = entry.role || 'body';
    const style = ROLE_STYLE[role] || ROLE_STYLE.body;
    const size = TYPE_SCALE[role] || TYPE_SCALE.body;
    let textMesh = null;
    try {
      textMesh = createMSDFText(ctx, {
        text: entry.text || '',
        font: style.family,
        weight: style.weight,
        size,
        color: style.color,
        letterSpacing: style.letterSpacing,
        lineHeight: style.lineHeight,
        align: 'center',
        anchorX: 'center',
        anchorY: 'middle',
        maxWidth: 6,
      });
    } catch (err) {
      textMesh = null;
    }
    if (!textMesh) return;
    textMesh.position.set(0, roleY[role] ?? bodyY, 0.02);
    textMesh.userData.role = role;
    root.add(textMesh);
    textObjects.push(textMesh);
  });

  // ---------- cinematic primitives ----------
  const primList = Array.isArray(config.cinematicPrimitives) ? config.cinematicPrimitives : [];
  primList.forEach((prim) => {
    const fn = ctx.primitives && ctx.primitives[prim.name];
    if (typeof fn !== 'function') return;
    const target = prim.name === 'depth-rotate' ? tiltGroup : turntable;
    let controller = null;
    try {
      controller = fn(target, prim.params || {});
    } catch (err) {
      controller = null;
    }
    primitiveControllers.push({ name: prim.name, controller });
  });

  // ---------- pointer handlers composed from primitive controllers ----------
  const baseHandlers = {};
  primitiveControllers.forEach(({ controller }) => {
    if (!controller) return;
    ['onPointerOver', 'onPointerOut', 'onPointerMove', 'onClick'].forEach((key) => {
      if (typeof controller[key] === 'function') {
        const prev = baseHandlers[key];
        baseHandlers[key] = (event) => {
          prev?.(event);
          controller[key](event);
        };
      }
    });
  });

  // weighted-settle: release settles with overshoot scale 1.04 -> 1.0, power4.out, 0.9s
  let settleTween = null;
  const prevPointerOut = baseHandlers.onPointerOut;
  baseHandlers.onPointerOut = (event) => {
    prevPointerOut?.(event);
    settleTween?.kill();
    tiltGroup.scale.set(1.04, 1.04, 1.04);
    settleTween = gsap.to(tiltGroup.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out',
    });
  };

  root.userData.handlers = baseHandlers;

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    settleTween?.kill();
    settleTween = null;

    primitiveControllers.forEach(({ controller }) => {
      if (controller && typeof controller.dispose === 'function') {
        controller.dispose();
      }
    });
    primitiveControllers.length = 0;

    disposables.forEach((resource) => {
      resource?.dispose?.();
    });
    disposables.length = 0;

    textObjects.forEach((obj) => {
      obj.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material && typeof child.material.dispose === 'function') {
          child.material.dispose();
        }
      });
    });
    textObjects.length = 0;

    // Note: watchScene is cloned from a cached GLB (ctx.glbLoader cache) — its
    // shared geometries/materials/textures are intentionally NOT disposed here.
    root.clear();
  };

  return root;
}
